import{_ as e,c as i,o as r,ag as t}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Guía de uso","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/usage.md","filePath":"es/guide/usage.md","lastUpdated":1794112334000}'),o={name:"es/guide/usage.md"};function n(l,a,s,d,c,m){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="guia-de-uso" tabindex="-1">Guía de uso <a class="header-anchor" href="#guia-de-uso" aria-label="Permalink to &quot;Guía de uso&quot;">​</a></h1><h2 id="navegacion-basica" tabindex="-1">Navegación básica <a class="header-anchor" href="#navegacion-basica" aria-label="Permalink to &quot;Navegación básica&quot;">​</a></h2><h3 id="abrir-imagenes" tabindex="-1">Abrir imágenes <a class="header-anchor" href="#abrir-imagenes" aria-label="Permalink to &quot;Abrir imágenes&quot;">​</a></h3><ul><li><strong>Menú Archivo</strong>: haz clic en Archivo &gt; Abrir para seleccionar imágenes individuales</li><li><strong>Vista de carpeta</strong>: haz clic en Archivo &gt; Abrir carpeta para explorar un directorio completo</li><li><strong>Arrastrar y soltar</strong>: arrastra archivos de imagen o carpetas directamente a la ventana de la aplicación</li><li><strong>Extensión de Chrome</strong>: haz clic en el icono de la extensión en cualquier sitio web para ver todas las imágenes</li></ul><h2 id="extension-de-sincronizacion-con-el-finder" tabindex="-1">Extensión de sincronización con el Finder <a class="header-anchor" href="#extension-de-sincronizacion-con-el-finder" aria-label="Permalink to &quot;Extensión de sincronización con el Finder&quot;">​</a></h2><h3 id="procesamiento-rapido-de-imagenes-desde-el-finder" tabindex="-1">Procesamiento rápido de imágenes desde el Finder <a class="header-anchor" href="#procesamiento-rapido-de-imagenes-desde-el-finder" aria-label="Permalink to &quot;Procesamiento rápido de imágenes desde el Finder&quot;">​</a></h3><p>La extensión de sincronización añade un botón de Nicasa a la barra de herramientas del Finder para procesar imágenes rápidamente:</p><ol><li>Selecciona una o varias imágenes en el Finder</li><li>Haz clic en el botón de Nicasa de la barra de herramientas</li><li>Elige <strong>Optimizador de imágenes</strong> para comprimir archivos o <strong>Editor de imágenes con IA</strong> para mejorar imágenes</li><li>Nicasa se abrirá automáticamente y procesará los archivos seleccionados</li></ol><h3 id="formatos-compatibles" tabindex="-1">Formatos compatibles <a class="header-anchor" href="#formatos-compatibles" aria-label="Permalink to &quot;Formatos compatibles&quot;">​</a></h3><p>La extensión funciona con archivos JPG, PNG, GIF, BMP, WebP, SVG, TIFF e ICO.</p><h3 id="vista-de-miniaturas" tabindex="-1">Vista de miniaturas <a class="header-anchor" href="#vista-de-miniaturas" aria-label="Permalink to &quot;Vista de miniaturas&quot;">​</a></h3><p>La interfaz principal muestra miniaturas de tus imágenes:</p><ul><li><strong>Clic</strong>: selecciona una imagen</li><li><strong>Doble clic</strong>: abre en vista completa</li><li><strong>Clic derecho</strong>: accede al menú contextual con opciones</li></ul><h3 id="modo-de-vista-completa" tabindex="-1">Modo de vista completa <a class="header-anchor" href="#modo-de-vista-completa" aria-label="Permalink to &quot;Modo de vista completa&quot;">​</a></h3><p>Al ver una imagen a pantalla completa:</p><ul><li><strong>Zoom</strong>: usa la rueda del ratón o los controles de zoom</li><li><strong>Desplazamiento</strong>: haz clic y arrastra para moverte por imágenes ampliadas</li><li><strong>Navegación</strong>: usa las teclas de flecha o los botones en pantalla para ir a la imagen siguiente o anterior</li></ul><h2 id="funcion-de-captura-de-pantalla" tabindex="-1">Función de captura de pantalla <a class="header-anchor" href="#funcion-de-captura-de-pantalla" aria-label="Permalink to &quot;Función de captura de pantalla&quot;">​</a></h2><h3 id="hacer-capturas" tabindex="-1">Hacer capturas <a class="header-anchor" href="#hacer-capturas" aria-label="Permalink to &quot;Hacer capturas&quot;">​</a></h3><ol><li>Haz clic en el botón de captura de la barra de herramientas o usa el atajo de teclado</li><li>Selecciona el área que quieres capturar</li><li>La captura se abrirá automáticamente en Nicasa para editarla</li></ol><h3 id="permiso-de-grabacion-de-pantalla" tabindex="-1">Permiso de grabación de pantalla <a class="header-anchor" href="#permiso-de-grabacion-de-pantalla" aria-label="Permalink to &quot;Permiso de grabación de pantalla&quot;">​</a></h3><p>Para la función de captura, Nicasa necesita el permiso de grabación de pantalla:</p><ol><li>Ve a Ajustes del Sistema &gt; Privacidad y seguridad &gt; Grabación de pantalla</li><li>Marca la casilla junto a Nicasa</li><li>Reinicia Nicasa si es necesario</li></ol><h2 id="editor-de-imagenes-con-ia" tabindex="-1">Editor de imágenes con IA <a class="header-anchor" href="#editor-de-imagenes-con-ia" aria-label="Permalink to &quot;Editor de imágenes con IA&quot;">​</a></h2><h3 id="descripcion-del-editor-de-ia" tabindex="-1">Descripción del editor de IA <a class="header-anchor" href="#descripcion-del-editor-de-ia" aria-label="Permalink to &quot;Descripción del editor de IA&quot;">​</a></h3><p>Nicasa incluye potentes herramientas de IA para mejorar imágenes:</p><ul><li><strong>Mejora automática</strong>: mejora la calidad de la imagen automáticamente</li><li><strong>Recorte inteligente</strong>: sugerencias inteligentes de recorte</li><li><strong>Corrección de color</strong>: ajustes de color impulsados por IA</li><li><strong>Reducción de ruido</strong>: elimina el ruido y el grano</li><li><strong>Enfoque</strong>: enfoque inteligente sin artefactos</li></ul><h3 id="herramienta-de-relleno-inpainting" tabindex="-1">Herramienta de relleno (inpainting) <a class="header-anchor" href="#herramienta-de-relleno-inpainting" aria-label="Permalink to &quot;Herramienta de relleno (inpainting)&quot;">​</a></h3><p>La herramienta de relleno te permite:</p><ul><li>Eliminar objetos no deseados de las imágenes</li><li>Rellenar partes faltantes de forma inteligente</li><li>Restaurar áreas dañadas</li><li>Limpiar fondos</li></ul><h2 id="modo-superposicion-transparente" tabindex="-1">Modo superposición transparente <a class="header-anchor" href="#modo-superposicion-transparente" aria-label="Permalink to &quot;Modo superposición transparente&quot;">​</a></h2><p>Perfecto para diseñadores y artistas:</p><ol><li>Abre una imagen en Nicasa</li><li>Activa el modo superposición desde el menú Visualización</li><li>Ajusta la transparencia con el control deslizante</li><li>La imagen se mantendrá por encima de todas las demás ventanas</li><li>Úsalo para calcar, consultar referencias o comparar interfaces</li></ol><h2 id="atajos-de-teclado" tabindex="-1">Atajos de teclado <a class="header-anchor" href="#atajos-de-teclado" aria-label="Permalink to &quot;Atajos de teclado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atajo</th><th>Acción</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Abrir archivo</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>Abrir carpeta</td></tr><tr><td><code>Space</code></td><td>Imagen siguiente</td></tr><tr><td><code>Shift+Space</code></td><td>Imagen anterior</td></tr><tr><td><code>Cmd+F</code></td><td>Alternar pantalla completa</td></tr><tr><td><code>Cmd+W</code></td><td>Cerrar ventana</td></tr><tr><td><code>Cmd+Q</code></td><td>Salir de la aplicación</td></tr><tr><td><code>Delete</code></td><td>Eliminar la imagen actual</td></tr><tr><td><code>Cmd+S</code></td><td>Hacer captura de pantalla</td></tr><tr><td><code>Cmd+E</code></td><td>Abrir el editor de IA</td></tr><tr><td><code>Cmd+T</code></td><td>Alternar modo superposición</td></tr></tbody></table><h2 id="integracion-con-la-extension-de-chrome" tabindex="-1">Integración con la extensión de Chrome <a class="header-anchor" href="#integracion-con-la-extension-de-chrome" aria-label="Permalink to &quot;Integración con la extensión de Chrome&quot;">​</a></h2><h3 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h3><ol><li>Instala la <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">extensión de Chrome de Nicasa</a></li><li>El icono de la extensión aparecerá en la barra de herramientas del navegador</li></ol><h3 id="uso" tabindex="-1">Uso <a class="header-anchor" href="#uso" aria-label="Permalink to &quot;Uso&quot;">​</a></h3><ol><li>Visita cualquier sitio web</li><li>Haz clic en el icono de la extensión de Nicasa</li><li>Verás todas las imágenes de la página en una cuadrícula</li><li>Haz clic en cualquier imagen para abrirla en Nicasa</li><li>Usa todas las funciones de Nicasa con imágenes web</li></ol><h2 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h2><p>Accede a los ajustes desde Nicasa &gt; Preferencias:</p><ul><li><strong>General</strong>: carpeta predeterminada, idioma, tema</li><li><strong>Visualización</strong>: tamaño de miniaturas, comportamiento del zoom, animaciones</li><li><strong>Editor</strong>: preferencias de herramientas de IA, mejoras predeterminadas</li><li><strong>Extensiones</strong>: ajustes de la extensión de Chrome</li><li><strong>Privacidad</strong>: preferencias de recopilación de datos</li></ul><h2 id="formatos-compatibles-1" tabindex="-1">Formatos compatibles <a class="header-anchor" href="#formatos-compatibles-1" aria-label="Permalink to &quot;Formatos compatibles&quot;">​</a></h2><p>Nicasa admite todos los formatos de imagen habituales:</p><ul><li><p><strong>Estándar</strong>: JPEG, PNG, GIF, BMP, TIFF, WebP</p></li><li><p><strong>RAW</strong>: CR2, NEF, ARW, DNG (con conversión)</p></li><li><p><strong>Vectorial</strong>: SVG (con rasterización)</p></li><li><p><strong>Animados</strong>: GIF, APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF (estático)</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC (en sistemas compatibles)</p></li></ul><h2 id="consejos-y-trucos" tabindex="-1">Consejos y trucos <a class="header-anchor" href="#consejos-y-trucos" aria-label="Permalink to &quot;Consejos y trucos&quot;">​</a></h2><ul><li>Usa la barra de búsqueda para encontrar imágenes por nombre de archivo</li><li>Crea colecciones organizando imágenes en carpetas</li><li>Usa el sistema de valoraciones para marcar tus imágenes favoritas</li><li>Exporta imágenes en distintos formatos desde el menú Archivo</li></ul>',47)])])}const h=e(o,[["render",n]]);export{u as __pageData,h as default};
